from dataclasses import dataclass


@dataclass
class Num:
    v: int


@dataclass
class Add:
    l: 'Expr'
    r: 'Expr'


@dataclass
class Mul:
    l: 'Expr'
    r: 'Expr'


Expr = Num | Add | Mul


def eval_expr(e: Expr) -> int:
    """Evaluate an arithmetic expression tree.

    Num evaluates to its value, Add to the sum of its operands' values,
    and Mul to the product of its operands' values.
    """
    match e:
        case Num(v=v):
            return v
        case Add(l=l, r=r):
            return eval_expr(l) + eval_expr(r)
        case Mul(l=l, r=r):
            return eval_expr(l) * eval_expr(r)


def test_num() -> None:
    assert eval_expr(Num(7)) == 7
    assert eval_expr(Num(0)) == 0
    assert eval_expr(Num(-3)) == -3


def test_add() -> None:
    assert eval_expr(Add(Num(2), Num(3))) == 5
    assert eval_expr(Add(Num(-2), Num(2))) == 0


def test_mul() -> None:
    assert eval_expr(Mul(Num(4), Num(5))) == 20
    assert eval_expr(Mul(Num(-4), Num(5))) == -20
    assert eval_expr(Mul(Num(0), Num(99))) == 0


def test_nested() -> None:
    # (1 + 2) * (3 + 4) = 21
    e = Mul(Add(Num(1), Num(2)), Add(Num(3), Num(4)))
    assert eval_expr(e) == 21
    # 2 + 3 * 4 = 14
    assert eval_expr(Add(Num(2), Mul(Num(3), Num(4)))) == 14
    # (2 + 3) * 4 = 20
    assert eval_expr(Mul(Add(Num(2), Num(3)), Num(4))) == 20


def test_unbalanced_deep() -> None:
    e: Expr = Num(0)
    for i in range(1, 101):
        e = Add(e, Num(i))
    assert eval_expr(e) == 5050


def test_identity_elements() -> None:
    assert eval_expr(Add(Num(9), Num(0))) == 9
    assert eval_expr(Mul(Num(9), Num(1))) == 9


def test_large_values() -> None:
    big = 10**12
    assert eval_expr(Mul(Num(big), Num(big))) == 10**24
